//! The own JSON reader and writer against references (DESIGN 7.3a): JSONTestSuite,
//! `serde_json` on random documents and random edits of them, and tables generated by
//! Node (`JSON.stringify`, `String(Number(x))`). Tests never run Node: the tables are
//! hardcoded, each with the command that produced it.
//!
//! The module is crate-private, so it is included here with `#[path]` (the public API
//! stays as it is; `cargo mutants` still sees these tests, the source file is the same).
#![cfg(not(target_arch = "wasm32"))]

#[path = "../src/json.rs"]
#[allow(dead_code)]
mod json;

use json::{Event, JsonError, JsonErrorKind, MAX_DEPTH, Reader, number_to_js_string, write_str};
use proptest::prelude::*;
use proptest::test_runner::{Config, RngAlgorithm, TestCaseError, TestRng, TestRunner};
use serde_json::{Map, Value};
use std::borrow::Cow;
use std::path::PathBuf;

/// Rebuilds a `serde_json::Value` from the event stream, checking that the stream is well
/// formed (keys only in objects, ends match starts, one root, `None` stays `None`).
fn parse(input: &[u8]) -> Result<Value, JsonError> {
    let mut r = Reader::new(input);
    // (container, key it goes under in its parent)
    let mut stack: Vec<(Value, Option<String>)> = Vec::new();
    let mut key: Option<String> = None;
    let mut root = None;
    while let Some(ev) = r.next()? {
        assert!(root.is_none(), "event after the root value: {ev:?}");
        let v = match ev {
            Event::ObjectStart => {
                stack.push((Value::Object(Map::new()), key.take()));
                continue;
            }
            Event::ArrayStart => {
                stack.push((Value::Array(Vec::new()), key.take()));
                continue;
            }
            Event::ObjectEnd | Event::ArrayEnd => {
                let (v, k) = stack.pop().expect("end without start");
                assert_eq!(v.is_object(), ev == Event::ObjectEnd, "mismatched end");
                assert!(key.is_none(), "key without value");
                key = k;
                v
            }
            Event::Key(k) => {
                assert!(matches!(stack.last(), Some((Value::Object(_), _))) && key.is_none());
                key = Some(k.into_owned());
                continue;
            }
            Event::Str(s) => Value::String(s.into_owned()),
            Event::Num(n) => serde_json::from_str(n).expect("serde_json reads the number text"),
            Event::Bool(b) => Value::Bool(b),
            Event::Null => Value::Null,
        };
        match stack.last_mut() {
            None => root = Some(v),
            Some((Value::Object(m), _)) => {
                m.insert(key.take().expect("value without key"), v);
            }
            Some((Value::Array(a), _)) => a.push(v),
            Some(_) => unreachable!(),
        }
    }
    assert_eq!(r.offset(), input.len(), "stopped before the end");
    assert_eq!(r.next(), Ok(None), "None is final");
    Ok(root.expect("Ok(None) before any value"))
}

/// Drains the reader: `Ok(())` when the whole input is one valid document.
fn accepts(input: &[u8]) -> Result<(), JsonError> {
    let mut r = Reader::new(input);
    while r.next()?.is_some() {}
    Ok(())
}

fn suite_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/json-test-suite/test_parsing")
}

/// Decisions on the implementation-defined `i_` cases: `Ok(())` accepted, `Err(kind)`
/// rejected with that error. Reasons in the comments; see also the header of `src/json.rs`.
const I_DECISIONS: &[(&str, Result<(), JsonErrorKind>)] = {
    use JsonErrorKind::*;
    &[
        // Grammar-valid numbers: kept as text, magnitude not checked. JS reads them as
        // ±Infinity, 0 or a rounded value; so does `number_to_js_string`.
        ("i_number_double_huge_neg_exp.json", Ok(())),
        ("i_number_huge_exp.json", Ok(())),
        ("i_number_neg_int_huge_exp.json", Ok(())),
        ("i_number_pos_double_huge_exp.json", Ok(())),
        ("i_number_real_neg_overflow.json", Ok(())),
        ("i_number_real_pos_overflow.json", Ok(())),
        ("i_number_real_underflow.json", Ok(())),
        ("i_number_too_big_neg_int.json", Ok(())),
        ("i_number_too_big_pos_int.json", Ok(())),
        ("i_number_very_big_negative_int.json", Ok(())),
        // Lone or broken surrogates in `\u` escapes: a `str` cannot hold them, and U+FFFD
        // would silently change a translation. Rejected (JSON.parse accepts them).
        ("i_object_key_lone_2nd_surrogate.json", Err(LoneSurrogate)),
        (
            "i_string_1st_surrogate_but_2nd_missing.json",
            Err(LoneSurrogate),
        ),
        (
            "i_string_1st_valid_surrogate_2nd_invalid.json",
            Err(LoneSurrogate),
        ),
        (
            "i_string_incomplete_surrogate_and_escape_valid.json",
            Err(LoneSurrogate),
        ),
        (
            "i_string_incomplete_surrogate_pair.json",
            Err(LoneSurrogate),
        ),
        (
            "i_string_incomplete_surrogates_escape_valid.json",
            Err(LoneSurrogate),
        ),
        ("i_string_invalid_lonely_surrogate.json", Err(LoneSurrogate)),
        ("i_string_invalid_surrogate.json", Err(LoneSurrogate)),
        (
            "i_string_inverted_surrogates_U+1D11E.json",
            Err(LoneSurrogate),
        ),
        ("i_string_lone_second_surrogate.json", Err(LoneSurrogate)),
        // Invalid UTF-8 (RFC 8259 8.1: JSON text is UTF-8). Rejected.
        ("i_string_invalid_utf-8.json", Err(InvalidUtf8)),
        ("i_string_iso_latin_1.json", Err(InvalidUtf8)),
        (
            "i_string_lone_utf8_continuation_byte.json",
            Err(InvalidUtf8),
        ),
        ("i_string_not_in_unicode_range.json", Err(InvalidUtf8)),
        ("i_string_overlong_sequence_2_bytes.json", Err(InvalidUtf8)),
        ("i_string_overlong_sequence_6_bytes.json", Err(InvalidUtf8)),
        (
            "i_string_overlong_sequence_6_bytes_null.json",
            Err(InvalidUtf8),
        ),
        ("i_string_truncated-utf-8.json", Err(InvalidUtf8)),
        ("i_string_UTF-8_invalid_sequence.json", Err(InvalidUtf8)),
        ("i_string_UTF8_surrogate_U+D800.json", Err(InvalidUtf8)),
        // UTF-16 input: only UTF-8 is read; the first non-ASCII / NUL byte is unexpected.
        ("i_string_UTF-16LE_with_BOM.json", Err(UnexpectedByte)),
        ("i_string_utf16BE_no_BOM.json", Err(UnexpectedByte)),
        ("i_string_utf16LE_no_BOM.json", Err(UnexpectedByte)),
        // Deeper than MAX_DEPTH (128).
        ("i_structure_500_nested_arrays.json", Err(TooDeep)),
        // A UTF-8 BOM is skipped (locale files saved by Windows editors).
        ("i_structure_UTF-8_BOM_empty_object.json", Ok(())),
    ]
};

/// Scenario: the whole JSONTestSuite corpus. Every `y_` file reads to the same value as
/// `serde_json`, every `n_` file is an error, every `i_` file gets its recorded decision.
#[test]
fn json_test_suite() {
    let mut names: Vec<String> = std::fs::read_dir(suite_dir())
        .expect("fixtures/json-test-suite/test_parsing")
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .collect();
    names.sort();
    let (mut y, mut n, mut i) = (0, 0, 0);
    for name in &names {
        let bytes = std::fs::read(suite_dir().join(name)).unwrap();
        match &name[..2] {
            "y_" => {
                y += 1;
                let expected: Value = serde_json::from_slice(&bytes)
                    .unwrap_or_else(|e| panic!("{name}: serde_json: {e}"));
                let got = parse(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
                assert_eq!(got, expected, "{name}");
            }
            "n_" => {
                n += 1;
                let e = accepts(&bytes).expect_err(name);
                assert!(
                    e.offset <= bytes.len(),
                    "{name}: offset {} past the end",
                    e.offset
                );
            }
            "i_" => {
                i += 1;
                let decision = I_DECISIONS
                    .iter()
                    .find(|(f, _)| f == name)
                    .unwrap_or_else(|| panic!("{name}: no recorded decision"))
                    .1;
                assert_eq!(accepts(&bytes).map_err(|e| e.kind), decision, "{name}");
            }
            _ => panic!("unexpected file {name}"),
        }
    }
    assert_eq!(i, I_DECISIONS.len(), "a recorded i_ decision has no file");
    assert!(y >= 95 && n >= 188, "corpus incomplete: {y} y_, {n} n_");
}

/// Scenario: hand-written broken inputs, one per error kind, give the kind and the byte
/// offset where reading stopped, and the message the catalog shows.
#[test]
fn errors_name_the_kind_and_the_byte() {
    use JsonErrorKind::*;
    let cases: &[(&[u8], usize, JsonErrorKind)] = &[
        (b"", 0, UnexpectedEof),
        (b"   ", 3, UnexpectedEof),
        (b"[", 1, UnexpectedEof),
        (b"[1", 2, UnexpectedEof),
        (b"{\"a\"", 4, UnexpectedEof),
        (b"{\"a\":1", 6, UnexpectedEof),
        (b"{", 1, UnexpectedEof),
        (b"{\"a\":1,", 7, UnexpectedEof),
        (b"\"abc", 4, UnexpectedEof),
        (b"\"a\\", 3, UnexpectedEof),
        (b"\"\\u12", 5, UnexpectedEof),
        (b"]", 0, UnexpectedByte),
        (b"[,1]", 1, UnexpectedByte),
        (b"[1,]", 3, UnexpectedByte),
        (b"tru", 0, UnexpectedByte),
        (b"nul", 0, UnexpectedByte),
        (b"fals", 0, UnexpectedByte),
        (b"[True]", 1, UnexpectedByte),
        (b"{1:2}", 1, ExpectedKey),
        (b"{\"a\":1,}", 7, ExpectedKey),
        (b"{\"a\" 1}", 5, ExpectedColon),
        (b"[1 2]", 3, ExpectedCommaOrEnd),
        (b"[1}", 2, ExpectedCommaOrEnd),
        (b"{\"a\":1]", 6, ExpectedCommaOrEnd),
        (b"-", 1, InvalidNumber),
        (b"-a", 1, InvalidNumber),
        (b"1.", 2, InvalidNumber),
        (b"1.e5", 2, InvalidNumber),
        (b"1e", 2, InvalidNumber),
        (b"1e+", 3, InvalidNumber),
        (b"01", 1, TrailingCharacters),
        (b"[01]", 2, ExpectedCommaOrEnd),
        (b"\"\\x\"", 2, InvalidEscape),
        (b"\"\\u12G4\"", 5, InvalidEscape),
        (b"\"\\uD800\"", 1, LoneSurrogate),
        (b"\"ab\\uDC00\"", 3, LoneSurrogate),
        (b"\"\\uD800\\u0041\"", 1, LoneSurrogate),
        (b"\"\\uD800\\uE000\"", 1, LoneSurrogate),
        (b"\"\\uD800x\"", 1, LoneSurrogate),
        (b"\"a\tb\"", 2, ControlCharacter),
        (b"\"a\\n\x01\"", 4, ControlCharacter),
        (b"\"ab\xff\"", 3, InvalidUtf8),
        (b"\"\\n\xc3\"", 3, InvalidUtf8),
        (b"\"a\xc3\\n\"", 2, InvalidUtf8),
        (b"1 2", 2, TrailingCharacters),
        (b"{} x", 3, TrailingCharacters),
        (b"\xEF\xBB\xBF", 3, UnexpectedEof),
        (b"\xEF\xBB{}", 0, UnexpectedByte),
        (b"\x0c1", 0, UnexpectedByte),
    ];
    for &(input, offset, kind) in cases {
        let e = accepts(input).expect_err(&String::from_utf8_lossy(input));
        assert_eq!(
            (e.offset, e.kind),
            (offset, kind),
            "{:?}",
            String::from_utf8_lossy(input)
        );
    }
    let e = accepts(b"[1 2]").unwrap_err();
    assert_eq!(
        e.to_string(),
        "invalid JSON at byte 3: expected ',' or the end of the container"
    );
    let texts = [
        (UnexpectedEof, "unexpected end of input"),
        (UnexpectedByte, "unexpected byte"),
        (ExpectedKey, "expected a string key"),
        (ExpectedColon, "expected ':'"),
        (InvalidNumber, "invalid number"),
        (InvalidEscape, "invalid escape"),
        (LoneSurrogate, "lone surrogate in \\u escape"),
        (ControlCharacter, "control character in string"),
        (InvalidUtf8, "invalid UTF-8"),
        (TooDeep, "nesting deeper than 128"),
        (TrailingCharacters, "trailing characters"),
    ];
    for (kind, text) in texts {
        assert_eq!(
            JsonError { offset: 7, kind }.to_string(),
            format!("invalid JSON at byte 7: {text}")
        );
    }
    let _: &dyn std::error::Error = &e;
}

/// Scenario: a locale-like document read event by event, with offsets: strings without
/// escapes are borrowed from the input, strings with escapes are decoded copies, every
/// whitespace kind is skipped, and after the end the reader stays at `None`.
#[test]
fn events_borrow_and_track_offsets() {
    let doc = "\u{feff} {\"nav\" :{\"title\":\"Home\",\"x\\ty\":\"a\\\"b\\u00e9\\uD83D\\uDE00\\/\\b\\f\\n\\r\\t\\\\\"},\r\n\t\"n\":[-0.5e+3,true,false,null,[],{}]} ";
    let mut r = Reader::new(doc.as_bytes());
    assert_eq!(r.offset(), 3, "BOM skipped");
    let mut evs = Vec::new();
    while let Some(ev) = r.next().unwrap() {
        evs.push((ev, r.offset()));
    }
    assert_eq!(r.offset(), doc.len());
    let borrowed = |e: &Event<'_>| {
        matches!(
            e,
            Event::Key(Cow::Borrowed(_)) | Event::Str(Cow::Borrowed(_))
        )
    };
    let at = |s: &str| doc.find(s).unwrap() + s.len();
    assert_eq!(evs[0], (Event::ObjectStart, 5));
    assert_eq!(evs[1], (Event::Key("nav".into()), at("\"nav\" :")));
    assert!(borrowed(&evs[1].0));
    assert_eq!(evs[2].0, Event::ObjectStart);
    assert_eq!(evs[3].0, Event::Key("title".into()));
    assert_eq!(evs[4], (Event::Str("Home".into()), at("\"Home\"")));
    assert!(borrowed(&evs[3].0) && borrowed(&evs[4].0));
    assert_eq!(evs[5].0, Event::Key("x\ty".into()));
    assert_eq!(
        evs[6].0,
        Event::Str("a\"b\u{e9}\u{1F600}/\u{8}\u{c}\n\r\t\\".into())
    );
    assert!(!borrowed(&evs[5].0) && !borrowed(&evs[6].0));
    assert_eq!(evs[7].0, Event::ObjectEnd);
    assert_eq!(evs[8].0, Event::Key("n".into()));
    assert_eq!(evs[9].0, Event::ArrayStart);
    assert_eq!(evs[10], (Event::Num("-0.5e+3"), at("-0.5e+3")));
    let rest: Vec<Event<'_>> = evs[11..].iter().map(|(e, _)| e.clone()).collect();
    assert_eq!(
        rest,
        [
            Event::Bool(true),
            Event::Bool(false),
            Event::Null,
            Event::ArrayStart,
            Event::ArrayEnd,
            Event::ObjectStart,
            Event::ObjectEnd,
            Event::ArrayEnd,
            Event::ObjectEnd,
        ]
    );
    assert_eq!(r.next(), Ok(None));
    assert_eq!(r.offset(), doc.len());
    // Escapes decode the same in either hex case, and a pair to one astral char.
    assert_eq!(
        parse(br#""\u00E9\ud83d\uDe00""#).unwrap(),
        Value::String("\u{e9}\u{1F600}".into())
    );
    // Scalars at the top level, with surrounding whitespace.
    assert_eq!(parse(b" \"s\" ").unwrap(), Value::String("s".into()));
    assert_eq!(parse(b"\t12 ").unwrap(), serde_json::json!(12));
    assert_eq!(parse(b"\nnull\r").unwrap(), Value::Null);
    // A stray quote is not the end of a borrowed run.
    assert_eq!(
        parse(br#"["a","b"]"#).unwrap(),
        serde_json::json!(["a", "b"])
    );
}

/// Scenario: nesting up to MAX_DEPTH reads, one level more is `TooDeep` at the bracket
/// that crosses the limit, for arrays, objects and a mix (the kind of each level is
/// remembered across all 128 levels).
#[test]
fn depth_limit() {
    for open in ["[", "{\"k\":"] {
        let close = if open == "[" { "]" } else { "}" };
        let ok = format!("{}0{}", open.repeat(MAX_DEPTH), close.repeat(MAX_DEPTH));
        accepts(ok.as_bytes()).unwrap();
        let deep = format!(
            "{}0{}",
            open.repeat(MAX_DEPTH + 1),
            close.repeat(MAX_DEPTH + 1)
        );
        let e = accepts(deep.as_bytes()).unwrap_err();
        assert_eq!(
            (e.offset, e.kind),
            (open.len() * MAX_DEPTH, JsonErrorKind::TooDeep)
        );
    }
    // Alternating object / array levels: each end must match its own start.
    let mut doc = String::new();
    for i in 0..MAX_DEPTH {
        doc.push_str(if i % 2 == 0 { "{\"k\":" } else { "[" });
    }
    doc.push('1');
    for i in (0..MAX_DEPTH).rev() {
        doc.push_str(if i % 2 == 0 { "}" } else { "]" });
    }
    let v = parse(doc.as_bytes()).unwrap();
    assert!(v.is_object());
    let swapped = doc.replacen("]}", "}]", 1);
    assert_eq!(
        accepts(swapped.as_bytes()).unwrap_err().kind,
        JsonErrorKind::ExpectedCommaOrEnd
    );
}

// ---------------------------------------------------------------- random documents

/// A generated string: each char with an encoding choice (raw, short escape, `\u` lower
/// case, `\u` upper case; astral chars as a surrogate pair).
type GenStr = Vec<(char, u8)>;

#[derive(Debug, Clone)]
enum Doc {
    Null,
    Bool(bool),
    Num(String),
    Str(GenStr),
    Arr(Vec<Doc>),
    Obj(Vec<(GenStr, Doc)>),
}

/// Expected events, owned.
#[derive(Debug, Clone, PartialEq)]
enum Ev {
    ObjS,
    ObjE,
    ArrS,
    ArrE,
    Key(String),
    Str(String),
    Num(String),
    Bool(bool),
    Null,
}

impl From<Event<'_>> for Ev {
    fn from(e: Event<'_>) -> Self {
        match e {
            Event::ObjectStart => Ev::ObjS,
            Event::ObjectEnd => Ev::ObjE,
            Event::ArrayStart => Ev::ArrS,
            Event::ArrayEnd => Ev::ArrE,
            Event::Key(k) => Ev::Key(k.into_owned()),
            Event::Str(s) => Ev::Str(s.into_owned()),
            Event::Num(n) => Ev::Num(n.to_owned()),
            Event::Bool(b) => Ev::Bool(b),
            Event::Null => Ev::Null,
        }
    }
}

fn gen_char() -> impl Strategy<Value = char> {
    prop_oneof![
        3 => proptest::char::range('a', 'z'),
        1 => proptest::char::range('\u{0}', '\u{1f}'),
        1 => prop::sample::select(vec!['"', '\\', '/', ' ', '\u{7f}', '\u{2028}', '\u{feff}']),
        1 => proptest::char::range('\u{80}', '\u{7ff}'),
        1 => proptest::char::range('\u{800}', '\u{fffd}'),
        1 => proptest::char::range('\u{10000}', '\u{10ffff}'),
    ]
}

fn gen_str() -> impl Strategy<Value = GenStr> {
    prop::collection::vec((gen_char(), 0u8..4), 0..10)
}

fn gen_doc() -> impl Strategy<Value = Doc> {
    let leaf = prop_oneof![
        Just(Doc::Null),
        any::<bool>().prop_map(Doc::Bool),
        "-?(0|[1-9][0-9]{0,18})(\\.[0-9]{1,18})?([eE][+-]?[0-9]{1,2})?".prop_map(Doc::Num),
        gen_str().prop_map(Doc::Str),
    ];
    leaf.prop_recursive(20, 128, 6, |inner| {
        prop_oneof![
            prop::collection::vec(inner.clone(), 0..6).prop_map(Doc::Arr),
            prop::collection::vec((gen_str(), inner), 0..6).prop_map(Doc::Obj),
        ]
    })
}

/// Renders documents and their expected events; whitespace comes from a small LCG so a
/// case is reproducible from its seed.
struct Render {
    out: Vec<u8>,
    events: Vec<Ev>,
    ws: u64,
}

impl Render {
    fn ws(&mut self) {
        self.ws = self
            .ws
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let n = (self.ws >> 61) as usize; // 0..=7, mostly short
        for i in 0..n.saturating_sub(4) {
            self.out.push(b" \t\n\r"[(self.ws >> (8 * i)) as usize & 3]);
        }
    }

    fn string(&mut self, s: &GenStr) -> String {
        let mut text = String::new();
        self.out.push(b'"');
        for &(c, mode) in s {
            text.push(c);
            let short = match c {
                '"' => Some("\\\""),
                '\\' => Some("\\\\"),
                '/' => Some("\\/"),
                '\u{8}' => Some("\\b"),
                '\u{c}' => Some("\\f"),
                '\n' => Some("\\n"),
                '\r' => Some("\\r"),
                '\t' => Some("\\t"),
                _ => None,
            };
            let must = c == '"' || c == '\\' || c < '\u{20}';
            match (mode, short) {
                (0, _) if !must => self
                    .out
                    .extend_from_slice(c.encode_utf8(&mut [0; 4]).as_bytes()),
                (0 | 1, Some(e)) => self.out.extend_from_slice(e.as_bytes()),
                _ => {
                    let mut units = [0u16; 2];
                    for u in c.encode_utf16(&mut units) {
                        let hex = if mode == 3 {
                            format!("\\u{u:04X}")
                        } else {
                            format!("\\u{u:04x}")
                        };
                        self.out.extend_from_slice(hex.as_bytes());
                    }
                }
            }
        }
        self.out.push(b'"');
        text
    }

    fn doc(&mut self, d: &Doc) {
        self.ws();
        match d {
            Doc::Null => {
                self.out.extend_from_slice(b"null");
                self.events.push(Ev::Null);
            }
            Doc::Bool(b) => {
                self.out
                    .extend_from_slice(if *b { b"true" } else { b"false" });
                self.events.push(Ev::Bool(*b));
            }
            Doc::Num(n) => {
                self.out.extend_from_slice(n.as_bytes());
                self.events.push(Ev::Num(n.clone()));
            }
            Doc::Str(s) => {
                let t = self.string(s);
                self.events.push(Ev::Str(t));
            }
            Doc::Arr(items) => {
                self.out.push(b'[');
                self.events.push(Ev::ArrS);
                for (i, it) in items.iter().enumerate() {
                    if i > 0 {
                        self.out.push(b',');
                    }
                    self.doc(it);
                }
                self.ws();
                self.out.push(b']');
                self.events.push(Ev::ArrE);
            }
            Doc::Obj(items) => {
                self.out.push(b'{');
                self.events.push(Ev::ObjS);
                for (i, (k, v)) in items.iter().enumerate() {
                    if i > 0 {
                        self.out.push(b',');
                    }
                    self.ws();
                    let t = self.string(k);
                    self.events.push(Ev::Key(t));
                    self.ws();
                    self.out.push(b':');
                    self.doc(v);
                }
                self.ws();
                self.out.push(b'}');
                self.events.push(Ev::ObjE);
            }
        }
        self.ws();
    }
}

fn render(d: &Doc, seed: u64) -> (Vec<u8>, Vec<Ev>) {
    let mut r = Render {
        out: Vec::new(),
        events: Vec::new(),
        ws: seed,
    };
    r.doc(d);
    (r.out, r.events)
}

fn runner(cases: u32, seed: u8) -> TestRunner {
    let config = Config {
        cases,
        failure_persistence: None,
        ..Config::default()
    };
    TestRunner::new_with_rng(
        config,
        TestRng::from_seed(RngAlgorithm::ChaCha, &[seed; 32]),
    )
}

/// Scenario: random documents (nesting up to 20, escapes of every form, surrogate pairs,
/// every number shape, random whitespace, optional BOM) give exactly the generated event
/// stream, and the rebuilt value equals `serde_json`'s parse of the same text.
#[test]
fn random_documents_match_serde_json() {
    runner(768, 7)
        .run(
            &(gen_doc(), any::<u64>(), any::<bool>()),
            |(doc, seed, bom)| {
                let (text, expected) = render(&doc, seed);
                let mut input = if bom {
                    b"\xEF\xBB\xBF".to_vec()
                } else {
                    Vec::new()
                };
                input.extend_from_slice(&text);

                let mut r = Reader::new(&input);
                let mut got = Vec::new();
                while let Some(ev) = r.next().map_err(|e| {
                    TestCaseError::fail(format!("{e}: {}", String::from_utf8_lossy(&input)))
                })? {
                    got.push(Ev::from(ev));
                }
                prop_assert_eq!(got, expected);
                let oracle: Value = serde_json::from_slice(&text)
                    .map_err(|e| TestCaseError::fail(e.to_string()))?;
                prop_assert_eq!(parse(&input).unwrap(), oracle);
                Ok(())
            },
        )
        .unwrap();
}

/// Scenario: random edits of valid documents (bytes deleted, inserted, replaced). The
/// reader accepts exactly what `serde_json` accepts: no trailing commas, no comments, no
/// leading zeros, no raw control characters, no broken escapes or UTF-8.
#[test]
fn random_edits_accepted_iff_serde_json_accepts() {
    const ALPHABET: &[u8] = b"{}[],:\"\\ 019-+.eEtrufalsn/\x00\x1f\x7f\xc3\xa9\xff\t";
    let edit = (
        0u8..3,
        any::<prop::sample::Index>(),
        prop::sample::select(ALPHABET),
    );
    runner(2048, 11)
        .run(
            &(gen_doc(), any::<u64>(), prop::collection::vec(edit, 1..4)),
            |(doc, seed, edits)| {
                let (mut text, _) = render(&doc, seed);
                for (op, at, byte) in edits {
                    let i = at.index(text.len() + 1);
                    match op {
                        0 if i < text.len() => {
                            text.remove(i);
                        }
                        1 if i < text.len() => text[i] = byte,
                        _ => text.insert(i, byte),
                    }
                }
                let ours = accepts(&text);
                let oracle = serde_json::from_slice::<Value>(&text);
                match (&ours, &oracle) {
                    (Ok(()), Ok(_)) | (Err(_), Err(_)) => {}
                    // The one intended difference: magnitude is not checked (`i_number_*`).
                    (Ok(()), Err(e)) if e.to_string().starts_with("number out of range") => {}
                    _ => {
                        return Err(TestCaseError::fail(format!(
                            "ours {ours:?}, serde_json {oracle:?}: {:?}",
                            String::from_utf8_lossy(&text)
                        )));
                    }
                }
                if let Err(e) = ours {
                    prop_assert!(e.offset <= text.len());
                }
                Ok(())
            },
        )
        .unwrap();
}

// ---------------------------------------------------------------- writer and numbers

/// `JSON.stringify` of strings, generated with Node 22:
///
/// ```text
/// node scratch/stringify.js   # for each string x:
///   console.log(`(&[${code points}], ${JSON.stringify(JSON.stringify(x))}),`)
/// ```
/// with x in: "", "plain", "quote\"", "back\\slash", "slash/", "\b\f\n\r\t",
/// "\u0000\u0001\u001f", "\u007f", "\u2028\u2029", "\u00e9\u4e2d\ud83d\ude00", "a\u000bb",
/// "mix \"x\"\n\\ \u0010 end", "\u001e\u001b", "\u000e\u0019" (raw U+007F, U+2028/9 and
/// the non-ASCII output written here as Rust escapes).
const STRINGIFY: &[(&[u32], &str)] = &[
    (&[], "\"\""),
    (&[0x70, 0x6c, 0x61, 0x69, 0x6e], "\"plain\""),
    (&[0x71, 0x75, 0x6f, 0x74, 0x65, 0x22], "\"quote\\\"\""),
    (
        &[0x62, 0x61, 0x63, 0x6b, 0x5c, 0x73, 0x6c, 0x61, 0x73, 0x68],
        "\"back\\\\slash\"",
    ),
    (&[0x73, 0x6c, 0x61, 0x73, 0x68, 0x2f], "\"slash/\""),
    (&[0x8, 0xc, 0xa, 0xd, 0x9], "\"\\b\\f\\n\\r\\t\""),
    (&[0x0, 0x1, 0x1f], "\"\\u0000\\u0001\\u001f\""),
    (&[0x7f], "\"\u{7f}\""),
    (&[0x2028, 0x2029], "\"\u{2028}\u{2029}\""),
    (&[0xe9, 0x4e2d, 0x1f600], "\"\u{e9}\u{4e2d}\u{1f600}\""),
    (&[0x61, 0xb, 0x62], "\"a\\u000bb\""),
    (
        &[
            0x6d, 0x69, 0x78, 0x20, 0x22, 0x78, 0x22, 0xa, 0x5c, 0x20, 0x10, 0x20, 0x65, 0x6e, 0x64,
        ],
        "\"mix \\\"x\\\"\\n\\\\ \\u0010 end\"",
    ),
    (&[0x1e, 0x1b], "\"\\u001e\\u001b\""),
    (&[0xe, 0x19], "\"\\u000e\\u0019\""),
];

/// Scenario: the writer produces byte-for-byte what `JSON.stringify` does (table above),
/// appends to what is already in the buffer, and on random strings agrees with
/// `serde_json` (whose escape set equals `JSON.stringify`'s for valid Unicode: the table
/// is checked against both) and reads back through the own reader.
#[test]
fn write_str_matches_json_stringify() {
    for (cps, expected) in STRINGIFY {
        let s: String = cps.iter().map(|&c| char::from_u32(c).unwrap()).collect();
        let mut out = String::from("prefix:");
        write_str(&mut out, &s);
        assert_eq!(&out["prefix:".len()..], *expected, "{s:?}");
        assert_eq!(
            serde_json::to_string(&s).unwrap(),
            *expected,
            "serde_json, {s:?}"
        );
    }
    // All 32 control characters, the short escapes in place of \u00XX where JS has one.
    for b in 0u8..0x20 {
        let mut out = String::new();
        write_str(&mut out, &char::from(b).to_string());
        let expected = match b {
            8 => "\"\\b\"".to_string(),
            9 => "\"\\t\"".to_string(),
            10 => "\"\\n\"".to_string(),
            12 => "\"\\f\"".to_string(),
            13 => "\"\\r\"".to_string(),
            _ => format!("\"\\u{b:04x}\""),
        };
        assert_eq!(out, expected);
    }
    runner(1024, 3)
        .run(&prop::collection::vec(gen_char(), 0..24), |chars| {
            let s: String = chars.into_iter().collect();
            let mut out = String::new();
            write_str(&mut out, &s);
            prop_assert_eq!(&out, &serde_json::to_string(&s).unwrap());
            prop_assert_eq!(serde_json::from_str::<String>(&out).unwrap(), s.clone());
            let mut r = Reader::new(out.as_bytes());
            prop_assert_eq!(r.next().unwrap(), Some(Event::Str(Cow::Borrowed(&s))));
            prop_assert_eq!(r.next().unwrap(), None);
            Ok(())
        })
        .unwrap();
}

